package org.ev6.musicvibe;
import android.app.*;import android.content.*;import android.os.*;
/** Timer-only light control. No audio input, audio service, spectrum, or beat detection. */
public final class BreathService extends Service {
 HandlerThread worker;Handler h;volatile boolean running,quitting;Lights base;
 volatile long progress;Handler monitor;long lastReport;
 long startedAt,lastHeartbeat,lastStatusRequest;int firstIndex,lastColor=-1,lastBright=-1;long lastCycle=-1;java.util.Random random=new java.util.Random();String previousStatus="";
 final Object lock=new Object();byte[] data;long generation;
 final BroadcastReceiver receiver=new BroadcastReceiver(){public void onReceive(Context c,Intent i){byte[] b=i.getByteArrayExtra(Vehicle.SML_EXTRA);if(b!=null&&b.length==9){boolean changed;synchronized(lock){changed=!java.util.Arrays.equals(data,b);data=b.clone();generation++;lock.notifyAll();}if(changed)Diag.event("light_report","rgb="+(((b[0]&255)<<8)|(b[1]&255))+","+(((b[2]&255)<<8)|(b[3]&255))+","+(((b[4]&255)<<8)|(b[5]&255))+" brightness_raw="+(b[6]&255)+" dim_option_raw="+(b[7]&255)+" drive_raw="+(b[8]&255));}}};
 public void onCreate(){super.onCreate();Diag.init(this,"main");Options.load(this);progress=SystemClock.elapsedRealtime();monitor=new Handler();monitor.postDelayed(watchdog,2000);registerReceiver(receiver,new IntentFilter(Vehicle.SML_ACTION));worker=new HandlerThread("MusicVibeLights");worker.start();h=new Handler(worker.getLooper());}
 public IBinder onBind(Intent i){return null;}
 public int onStartCommand(Intent i,int flags,int id){final Intent command=i;final String action=i==null?"STOP":i.getAction();Diag.event("service_command","action="+action+" flags="+flags+" id="+id);h.post(new Runnable(){public void run(){if("CONFIG".equals(action)){try{Options.set(BreathService.this,command);startedAt=SystemClock.elapsedRealtime();firstIndex=lastColor<0?firstIndex:lastColor;lastCycle=-1;if(running)status("Breathing lights active; "+Options.period/1000.0+"-second cycle; "+Options.mode+"; OEM levels 1-5");else stopSelf();}catch(Exception e){Diag.event("options_error",e.toString());}}else if("BOOT".equals(action)){if(!running&&!quitting)boot();}else if("START".equals(action)){Store.f(BreathService.this,"manual-stop-boot").delete();if(!running&&!quitting)begin();}else shutdown("Stopped");}});return START_NOT_STICKY;}
 void status(String s){if(!s.equals(previousStatus)){previousStatus=s;Diag.event("status",s);Store.status(this,s);android.util.Log.i("MusicVibe",s);}}
 void foreground(){PendingIntent stop=PendingIntent.getService(this,1,new Intent(this,BreathService.class).setAction("STOP"),PendingIntent.FLAG_UPDATE_CURRENT);startForeground(60,new Notification.Builder(this).setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Music Vibe").setContentText("Breathing lights. Tap to stop and restore.").setContentIntent(stop).setOngoing(true).build());}
 boolean manual(){return Store.manualDisabled(this)||ColorMenuWatcher.colorSettingsOpen(this);}
 byte[] snapshot()throws Exception {long gen;synchronized(lock){gen=generation;}Vehicle.request();long until=SystemClock.elapsedRealtime()+2500;synchronized(lock){while(generation==gen&&SystemClock.elapsedRealtime()<until)lock.wait(100);if(generation==gen)throw new Exception("No fresh light response");return data.clone();}}
 void restore()throws Exception {if(base==null)return;for(int n=0;n<3;n++){if(manual()){handOff();return;}Vehicle.restore(base);if(RestoreCheck.await(this,base,new RestoreCheck.Reader(){public byte[] read()throws Exception{return snapshot();}},4000))return;if(manual()){handOff();return;}}throw new Exception("Restore readback mismatch (see restore_sample diagnostics)");}
 void begin(){try{beginAttempt();}catch(Exception e){fail(e);}}
 void beginAttempt()throws Exception {Diag.event("begin",Diag.health(this));Store.write(this,"owner-pid",Integer.toString(android.os.Process.myPid()));if(manual()){handOff();return;}foreground();if(Store.f(this,"restore.json").exists()){base=Store.baseline(this);restore();if(quitting)return;Store.restored(this);base=null;}base=Lights.decode(snapshot(),Vehicle.fade());if(base.drive!=1)throw new Exception("Turn off Link to Drive Mode first");Store.save(this,base);Store.beat(this);Store.write(this,"armed","1");startService(new Intent(this,RestoreGuard.class));firstIndex=BreathPattern.initialIndex(base);startedAt=SystemClock.elapsedRealtime();running=true;status("Breathing lights active; "+Options.period/1000.0+"-second cycle; "+Options.mode+"; OEM levels 1-5");h.post(tick);}
 void boot(){if(manual()){handOff();return;}foreground();status("Waiting for vehicle lights");final long until=SystemClock.elapsedRealtime()+120000;h.postDelayed(new Runnable(){public void run(){if(quitting||running)return;if(manual()){handOff();return;}try{Lights.decode(snapshot(),Vehicle.fade());beginAttempt();}catch(Exception e){Diag.event("boot_retry",e.toString()+" remaining_ms="+(until-SystemClock.elapsedRealtime()));if(SystemClock.elapsedRealtime()<until&&!quitting)h.postDelayed(this,4000);else fail(e);}}},12000);}
 final Runnable tick=new Runnable(){public void run(){if(!running||quitting)return;progress=SystemClock.elapsedRealtime();try{if(manual()){handOff();return;}if(!Store.armed(BreathService.this))throw new Exception("Restore guard revoked control");long now=SystemClock.elapsedRealtime();if(now-lastHeartbeat>=700){Store.beat(BreathService.this);lastHeartbeat=now;}if(now-lastStatusRequest>=30000){lastStatusRequest=now;try{Vehicle.request();}catch(Exception readError){Diag.event("light_report_request_error",readError.toString());}}long elapsed=now-startedAt;int bright=BreathPattern.brightness(elapsed);long cycle=elapsed/Options.period;int color=lastColor;if(cycle!=lastCycle){if("random".equals(Options.mode)){color=random.nextInt(Palette.COLORS.length-1);if(color>=lastColor)color++;}else{long step="counterclockwise".equals(Options.mode)?-cycle:cycle;color=(int)((firstIndex+step)%Palette.COLORS.length);if(color<0)color+=Palette.COLORS.length;}lastCycle=cycle;Diag.event("cycle","cycle="+cycle+" color_index="+color+" period_ms="+Options.period+" mode="+Options.mode);}if(color<0)color=firstIndex;if(color!=lastColor){int[] rgb=Palette.COLORS[color];Vehicle.rgb(rgb[0],rgb[1],rgb[2]);lastColor=color;}if(bright!=lastBright){Vehicle.brightness(bright);lastBright=bright;}h.postDelayed(this,100);}catch(Exception e){fail(e);}}};
 void handOff(){if(quitting)return;Diag.event("manual_handoff",Diag.health(this));quitting=true;running=false;h.removeCallbacks(tick);Store.markManual(this);try{Store.handedOff(this);}catch(Exception e){android.util.Log.e("MusicVibe","Handoff",e);}status("Disabled after OEM light settings; manual color preserved until next boot");stopForeground(true);stopSelf();}
 void fail(Exception e){Diag.event("service_failure",android.util.Log.getStackTraceString(e)+" "+Diag.health(this));android.util.Log.e("MusicVibe","Stopped",e);shutdown("Stopped: "+e.getMessage());}
 void shutdown(String reason){if(quitting)return;Diag.event("shutdown",reason+" "+Diag.health(this));if(manual()){handOff();return;}quitting=true;running=false;h.removeCallbacks(tick);Store.disarm(this);try{if(base==null&&Store.f(this,"restore.json").exists())base=Store.baseline(this);if(base!=null&&Store.f(this,"restore.json").exists()){restore();Store.restored(this);reason+="; original lights verified";}}catch(Exception e){reason+="; restore pending";startService(new Intent(this,RestoreGuard.class));}status(reason);stopForeground(true);stopSelf();}
 public void onTaskRemoved(Intent i){Diag.event("task_removed",String.valueOf(i));super.onTaskRemoved(i);}
 public void onTrimMemory(int level){Diag.event("trim_memory","level="+level);super.onTrimMemory(level);}
 public void onLowMemory(){Diag.event("low_memory",Diag.health(this));super.onLowMemory();}
 final Runnable watchdog=new Runnable(){public void run(){long now=SystemClock.elapsedRealtime();long lag=now-progress;if((running&&lag>2500)||now-lastReport>=30000){Diag.event(lag>2500&&running?"worker_stall":"health","running="+running+" quitting="+quitting+" tick_age_ms="+lag+" "+Diag.health(BreathService.this)+(lag>2500&&running?" stack="+Diag.stack(worker):""));lastReport=now;}if(!quitting)monitor.postDelayed(this,2000);}};
 public void onDestroy(){Diag.event("service_destroy",Diag.health(this));if(monitor!=null)monitor.removeCallbacks(watchdog);if(h!=null&&!quitting)h.post(new Runnable(){public void run(){shutdown("Service ended");try{unregisterReceiver(receiver);}catch(Exception e){}worker.quit();}});else{try{unregisterReceiver(receiver);}catch(Exception e){}if(worker!=null)worker.quit();}super.onDestroy();}
}
